<script setup lang="ts">
import {computed,ref,watch,onMounted,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import {useMeetingCreateFlow} from './useMeetingCreateFlow';import MeetingInfoDrawer from './MeetingInfoDrawer.vue';import MeetingInfoEditor from './MeetingInfoEditor.vue';import Icon from '../../shared/Icon.vue';import FuturePanels from './FuturePanels.vue';import LegacyRecordingFiles from '../recording/LegacyRecordingFiles.vue';import RecordingArchivePlayback from '../recording/RecordingArchivePlayback.vue';
const app=useApplication(),{session,pcmRecorder:native,create,recordingApi}=app,route=useRoute(),router=useRouter(),panels=ref<InstanceType<typeof FuturePanels>>();const infoEditorRef=ref<InstanceType<typeof MeetingInfoEditor>>();function closeInfo(){if(infoEditorRef.value?.cancel?.()??true)infoOpen.value=false;}
const infoOpen=ref(false),interruptDialog=ref<HTMLDialogElement>(),endDialog=ref<HTMLDialogElement>(),busy=ref(false),localError=ref<string|null>(null),endError=ref<string|null>(null),lastEnd=ref<'save'|'process'|null>(null),live=ref<HTMLElement>();
const actor=()=>session.current.value?.actor.enterpriseId??null,meeting=computed(()=>native.meetingId.value),active=computed(()=>native.phase.value==='RECORDING'),paused=computed(()=>native.phase.value==='PAUSED'),saving=computed(()=>busy.value||['SAVING','AUTHORIZING'].includes(native.phase.value)),failed=computed(()=>native.phase.value==='ERROR'),finished=computed(()=>native.record.value?.finished??false);
const parts=computed(()=>native.record.value?.parts.map((p,index)=>({id:p.partId,index:index+1,name:'录音片段 '+String(index+1).padStart(2,'0'),bytes:p.sampleCount*2,chunks:Array.from({length:p.finalSequence},(_,n)=>n+1),elapsedMs:p.sampleCount/16,savedElapsedMs:p.sampleCount/16,incomplete:false,state:index===native.record.value!.parts.length-1?(active.value?'RECORDING':paused.value?'PAUSED':finished.value?'SAVED':'INTERRUPTED'):'INTERRUPTED'}))??[]),savedParts=computed(()=>parts.value.filter(p=>p.bytes>0&&!['RECORDING','PAUSED'].includes(p.state)));
const r={...native},interrupted=computed(()=>!active.value&&!paused.value&&parts.value.length>0&&!finished.value),state=computed(()=>saving.value?'保存中':failed.value?'需要恢复保存':active.value?'录音中':paused.value?'已暂停':finished.value?'已结束采集':interrupted.value?'本段已中断':'等待麦克风授权');const label=computed(()=>failed.value?'重试保存':active.value?'暂停录音':paused.value?'继续录音':parts.value.length?'开始下一段':'重新授权并开始'),transcriptStatus=computed(()=>paused.value?'已暂停，内容保留':interrupted.value?'已中断，内容保留':'当前累计内容'),saveStatus=computed(()=>native.pendingCount.value?`${native.pendingCount.value} 个分片待服务端确认`:finished.value?'采集已封存，归档状态见下方':parts.value.some(p=>p.bytes>0)?'已获服务端保存确认':'等待录音数据');
function clock(ms:number){const t=Math.floor(Math.max(0,ms)/1000);return `${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}
const flow=useMeetingCreateFlow(create,actor,async id=>{await native.attach(id);await router.replace('/recording/'+id);app.setMeetingScope(id);return router.currentRoute.value.path==='/recording/'+id;});
async function initialize(){if(!actor())return;const id=typeof route.params.id==='string'?route.params.id:null;if(id){await native.attach(id);app.setMeetingScope(id);return;}const old=native.record.value??await native.restore();if(old&&!old.finished){await router.replace('/recording/'+old.meetingId);app.setMeetingScope(old.meetingId);}}
async function start(){if(busy.value||finished.value)return;busy.value=true;localError.value=null;try{await initialize();if(!meeting.value){await flow.open();if(flow.error.value)throw flow.error.value;}if(!meeting.value)throw Error('会议创建尚未确认，请重试原请求');await native.start();}catch(cause){localError.value=cause instanceof Error?cause.message:'无法开始录音';}finally{busy.value=false;}}
async function primary(){if(busy.value)return;localError.value=null;try{if(failed.value){await native.retry();return;}if(active.value){await native.pause();return;}if(paused.value){await native.resume();return;}await start();}catch(cause){localError.value=cause instanceof Error?cause.message:'录音操作尚未完成';}}
async function reconnect(){busy.value=true;localError.value=null;try{await native.reconnect();}catch(cause){localError.value=cause instanceof Error?cause.message:'恢复上传尚未完成';}finally{busy.value=false;}}
async function interrupt(){busy.value=true;localError.value=null;try{await native.interrupt();interruptDialog.value?.close();}catch(cause){localError.value=cause instanceof Error?cause.message:'本段保存未完成';}finally{busy.value=false;}}
async function end(){try{if(active.value)await native.pause();lastEnd.value=null;endError.value=null;endDialog.value?.showModal();}catch(cause){localError.value=cause instanceof Error?cause.message:'暂停未确认，请保留当前页面';}}
async function finish(action:'save'|'process'){if(busy.value)return;busy.value=true;lastEnd.value=action;endError.value=null;try{await native.finish();endDialog.value?.close();if(action==='process')await router.push('/meeting/'+meeting.value+'/processing');else await router.push('/meetings');}catch(cause){endError.value=cause instanceof Error?cause.message:'服务端保存尚未确认，请恢复上传后重试';}finally{busy.value=false;}}
let initializing:Promise<void>|null=null;async function load(){if(initializing)return initializing;initializing=initialize();try{await initializing;}catch(cause){localError.value=cause instanceof Error?cause.message:'录音记录暂不可用';}finally{initializing=null;}}
const stop=watch(()=>[actor(),route.params.id],()=>{if(actor())void load();},{immediate:true});onMounted(async()=>{if(!session.current.value)try{await session.refresh();}catch{/* Existing session feedback handles identity loss. */}await load();if(route.query.start==='1'){await router.replace({path:route.path,query:{}});await start();}});onUnmounted(()=>{stop();flow.dispose();});
</script>
<template><div class="layout"><div class="main"><header class="topbar"><RouterLink to="/meetings" class="topbar-home"><Icon name="list"/> 我的会议</RouterLink><span class="topbar-crumb">/ 在线录音</span></header><main class="content"><div class="ac-page acr-page"><header class="page-head"><div><h1 class="page-title">在线录音</h1><div class="page-desc">在线录音并实时转写，站内切换不影响录音，可继续处理其他工作。请保持当前标签页打开，刷新、关闭标签页或退出浏览器将中断录音。</div></div><button class="btn ghost" type="button" @click="router.push('/meetings')">返回会议列表</button></header>
 <section class="card acr-record-card" aria-label="会议录音"><div class="acr-record-top"><div class="acr-record-symbol" :class="active?'is-recording':'is-paused'"><Icon name="mic" :size="30"/><span></span></div><div class="acr-record-time"><strong id="ac-record-clock">{{clock(r.partElapsed.value)}}</strong><span id="ac-record-status">第{{parts.at(-1)?.index??1}}段 · {{state}}</span><small class="muted">累计录音 <time id="ac-record-total">{{clock(r.elapsed.value)}}</time></small></div><div class="acr-record-controls"><button class="acr-icon-button" :aria-label="label" :title="label" :disabled="saving||finished||!session.current.value" @click="primary"><Icon :name="failed?'refresh':active?'pause':'play'" :size="20"/></button><span class="acr-interrupt-slot"><button v-if="active||paused||saving" class="btn sm ghost" :disabled="saving||failed" @click="interruptDialog?.showModal()">中断本段</button></span><button class="acr-icon-button acr-stop" aria-label="结束录音" title="结束录音" :disabled="saving||failed||finished||!parts.length" @click="end"><svg width="19" height="19" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="5" y="5" width="14" height="14" rx="2"/></svg></button></div></div>
 <div class="acr-record-save small muted">已采集 {{parts.reduce((n,p)=>n+p.chunks.length,0)}} 个音频分片 · 保存范围约至 {{clock(parts.reduce((n,p)=>n+p.savedElapsedMs,0))}} · {{saveStatus}}</div><div v-if="savedParts.length" class="acr-saved-parts" aria-label="已记录录音段"><span class="acr-parts-caption">已记录录音 · {{savedParts.length}}段</span><div class="acr-saved-part-files"><div v-for="part in savedParts" :key="part.id" class="acr-saved-part"><Icon name="file" :size="12"/><span>第{{part.index}}段 · {{part.name}}</span><time>{{clock(part.elapsedMs)}}</time><small :title="part.incomplete?'仅保留可恢复范围，尾段可能缺失':''">{{part.state==='SYSTEM_INTERRUPTED'?'系统中断':part.state==='INTERRUPTED'?'中断保存':part.state==='SAVED'?'结束保存':'已保存'}}{{part.incomplete?' · 范围不完整':''}}</small></div></div></div>
 <div class="acr-record-feedback"><div v-if="localError||r.error.value" class="ac-error" role="alert">{{localError??r.error.value}}</div><div v-else-if="!active&&!paused&&parts.length&&!finished" class="small muted acr-interruption-note">本段已保存，可开始下一段。</div><div v-if="!parts.length" class="small muted acr-interruption-note">请允许麦克风权限并检查设备。<RouterLink to="/meetings" class="btn sm ghost">改为导入文件</RouterLink></div></div><div v-if="native.pendingCount.value" class="between mt12"><span class="small muted">未确认音频 {{native.pendingCount.value}} 个分片</span><button class="btn sm" :disabled="busy" @click="reconnect">恢复上传</button></div><div class="acr-subtle-tools"><button class="acr-tool" :disabled="!meeting" @click="infoOpen=true"><Icon name="edit" :size="14"/> 填写会议信息</button><span></span><button class="acr-tool" :disabled="!meeting" @click="panels?.open('materials')"><Icon name="file" :size="14"/> 添加背景资料</button></div></section>
 <section class="card acr-transcript-card"><div class="card-h"><div class="card-t">实时转写</div><span class="small muted">全部录音段 · {{transcriptStatus}}</span><button class="acr-tool ml-a" @click="live?.scrollTo({top:live.scrollHeight,behavior:'smooth'})"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 4v14m-5-5 5 5 5-5M5 21h14"/></svg> 回到最新</button></div><div ref="live" class="ac-live-text acr-live-text"><div class="acr-live-empty"><Icon name="mic" :size="26"/><p>等待会议内容</p><span>全部录音段的实时转写将在此累计展示。</span></div></div><div class="acr-simulation-note">音频经浏览器采集后分片保存。未确认音频保留在本机，最多缓存约十分钟；连接恢复后可补传。刷新、关闭或休眠可能中断设备，继续时将开启新段。实时识别尚未安装，当前不显示模拟文字。</div></section>
 <RecordingArchivePlayback v-if="finished&&native.record.value" :recording="native.record.value.session"/><LegacyRecordingFiles :meeting-id="meeting"/></div></main></div></div><MeetingInfoDrawer :open="infoOpen" :prevent-close="infoEditorRef?.closeBlocked??false" @close="closeInfo"><MeetingInfoEditor ref="infoEditorRef" v-if="infoOpen&&meeting&&app.infoScopeReady.value" :meeting-id="meeting" :eligible="!finished" @close="infoOpen=false"/></MeetingInfoDrawer><FuturePanels ref="panels"/>
 <dialog ref="interruptDialog" class="notice-dialog" aria-labelledby="record-interrupt-title"><h3 id="record-interrupt-title">中断本段录音</h3><p class="mt16">本段已确认音频将保留在服务端，未确认分片保留在本机；继续录音将开启下一段。</p><p v-if="localError||r.error.value" role="alert">{{localError??r.error.value}}</p><div class="flex mt16"><button class="btn" :disabled="busy" @click="interruptDialog?.close()">取消</button><button class="btn primary" :disabled="busy" @click="interrupt">保存本段</button></div></dialog>
 <dialog ref="endDialog" class="notice-dialog" aria-labelledby="record-end-title"><h3 id="record-end-title">结束录音</h3><p class="mt16">本次会议共{{parts.length}}段录音，累计{{clock(r.elapsed.value)}}。保存后可稍后继续处理，也可立即开始处理。</p><p class="small muted mt12">所有分片获得保存确认后才提交录音归档任务，归档完成后可回听。取消将返回当前暂停或中断状态，不自动恢复录音。</p><p v-if="endError" class="ac-error mt12" role="alert">{{endError}}</p><div class="flex mt16"><button class="btn" :disabled="busy" @click="endDialog?.close()">取消</button><button v-if="endError&&lastEnd" class="btn primary" :disabled="busy" @click="finish(lastEnd)">重试保存</button><button class="btn" :disabled="busy||!!endError" @click="finish('save')">保存</button><button class="btn primary" :disabled="busy||!!endError" @click="finish('process')">保存并查看进度</button></div></dialog>
</template>
